refreshCultStats.handler:
function refreshCultStats(args, ctx) {
  var attempts = 0;
  function tryRefresh() {
    attempts++;
    if (window.CultStats && typeof window.CultStats.refresh === "function") {
      requestAnimationFrame(function () {
        window.CultStats.refresh();
        ctx.triggerActionEvent("ready", {});
      });
      return;
    }
    if (attempts < 60) {
      setTimeout(tryRefresh, 100);
    }
  }
  tryRefresh();
}

ditherMotifs.handler:
function ditherMotifs(args, ctx) {
  var CELL = (typeof args.cell === "number" && args.cell > 0) ? args.cell : 9;
  var FPS = (typeof args.fps === "number" && args.fps > 0) ? args.fps : 18;
  var DOT = args.dotColor || "#0a0a0a";

  // Cancel any previous loop so SPA navigation / re-mount doesn't stack rAFs.
  if (window.__cultDitherStop) {
    try { window.__cultDitherStop(); } catch (e) {}
  }

  var raf = 0;
  var stopped = false;
  var lastDraw = 0;
  var frameInterval = 1000 / FPS;

  function collect() {
    return Array.prototype.slice.call(
      document.querySelectorAll("canvas[data-dither-motif]")
    );
  }

  function ensureSize(cv) {
    var dpr = window.devicePixelRatio || 1;
    var rect = cv.getBoundingClientRect();
    var w = Math.max(1, Math.round(rect.width));
    var h = Math.max(1, Math.round(rect.height));
    if (cv.__w !== w || cv.__h !== h || cv.__dpr !== dpr) {
      cv.width = Math.round(w * dpr);
      cv.height = Math.round(h * dpr);
      cv.__w = w;
      cv.__h = h;
      cv.__dpr = dpr;
    }
    return { w: w, h: h, dpr: dpr };
  }

  // Each motif returns intensity 0..1 for a normalized cell center (nx, ny in 0..1),
  // a centered coordinate (cx, cy in -1..1), and animation time t (seconds).
  function intensity(motif, nx, ny, cx, cy, t) {
    var d = Math.sqrt(cx * cx + cy * cy);
    var ang = Math.atan2(cy, cx);
    if (motif === "rings") {
      // concentric rings expanding outward
      var v = Math.cos(d * 9 - t * 2.2);
      return Math.pow(Math.max(0, v), 1.4) * (1 - d * 0.35);
    }
    if (motif === "mark") {
      // radial glyph: dense core, rotating petals
      var petals = Math.cos(ang * 6 + t * 1.4) * 0.5 + 0.5;
      var core = 1 - smooth(0.0, 0.85, d);
      var ring = Math.pow(Math.max(0, Math.cos(d * 7 - t * 1.6)), 2) * 0.6;
      return Math.max(core * (0.4 + petals * 0.6), ring * (1 - d * 0.4));
    }
    if (motif === "waveform") {
      // travelling sine band centered vertically
      var wave = Math.sin(nx * 12 - t * 3.0) * 0.5;
      var band = 1 - Math.min(1, Math.abs(cy - wave) * 5.5);
      var second = Math.sin(nx * 7 + t * 1.7) * 0.32;
      var band2 = (1 - Math.min(1, Math.abs(cy - second) * 7)) * 0.55;
      return Math.max(Math.max(0, band), Math.max(0, band2));
    }
    if (motif === "moire") {
      // two interfering diagonal gratings drifting apart
      var a = Math.sin((cx + cy) * 11 + t * 1.3);
      var b = Math.sin((cx - cy) * 11 - t * 0.9);
      return Math.pow(Math.max(0, a * b), 1.1);
    }
    if (motif === "gauge") {
      // sweeping arc / dial
      var sweep = (t * 0.7) % (Math.PI * 2);
      var arc = 1 - Math.min(1, Math.abs(d - 0.62) * 6);
      var head = Math.cos(ang - sweep + Math.PI) * 0.5 + 0.5;
      var ringFade = Math.max(0, arc);
      var tip = ringFade * Math.pow(head, 3);
      return Math.max(ringFade * 0.22, tip);
    }
    // fallback: gentle noise rings
    return Math.pow(Math.max(0, Math.cos(d * 8 - t * 2)), 1.4);
  }

  function smooth(a, b, x) {
    var t = Math.max(0, Math.min(1, (x - a) / (b - a)));
    return t * t * (3 - 2 * t);
  }

  function drawOne(cv, t) {
    var ctx2d = cv.getContext("2d");
    if (!ctx2d) return;
    var size = ensureSize(cv);
    var dpr = size.dpr;
    var W = cv.width, H = cv.height;
    var motif = cv.getAttribute("data-dither-motif") || "rings";
    var attrCell = parseFloat(cv.getAttribute("data-dither-cell"));
    var cell = (attrCell > 0 ? attrCell : CELL) * dpr;
    var color = cv.getAttribute("data-dither-color") || DOT;

    ctx2d.clearRect(0, 0, W, H);
    ctx2d.fillStyle = color;

    var cols = Math.max(2, Math.floor(W / cell));
    var rows = Math.max(2, Math.floor(H / cell));
    var stepX = W / cols;
    var stepY = H / rows;
    var maxDot = Math.min(stepX, stepY) * 0.46;

    for (var j = 0; j < rows; j++) {
      for (var i = 0; i < cols; i++) {
        var nx = (i + 0.5) / cols;
        var ny = (j + 0.5) / rows;
        var cx = (nx - 0.5) * 2;
        var cy = (ny - 0.5) * 2;
        var v = intensity(motif, nx, ny, cx, cy, t);
        if (v <= 0.06) continue;
        v = Math.min(1, v);
        var r = maxDot * v;
        if (r < 0.4) continue;
        var px = i * stepX + stepX / 2;
        var py = j * stepY + stepY / 2;
        // square dots for the blocky terminal look
        var s = r * 1.6;
        ctx2d.fillRect(px - s / 2, py - s / 2, s, s);
      }
    }
  }

  var start = 0;
  function frame(now) {
    if (stopped) return;
    if (!start) start = now;
    if (now - lastDraw >= frameInterval) {
      lastDraw = now;
      var t = (now - start) / 1000;
      var list = collect();
      for (var k = 0; k < list.length; k++) {
        drawOne(list[k], t);
      }
    }
    raf = requestAnimationFrame(frame);
  }

  function stop() {
    stopped = true;
    if (raf) cancelAnimationFrame(raf);
    window.__cultDitherStop = null;
  }
  window.__cultDitherStop = stop;

  // Wait until at least one canvas is mounted, then start.
  var attempts = 0;
  function begin() {
    attempts++;
    if (collect().length > 0) {
      raf = requestAnimationFrame(frame);
      ctx.triggerActionEvent("ready", {});
      return;
    }
    if (attempts < 60 && !stopped) {
      setTimeout(begin, 80);
    }
  }
  begin();
}

spiralAscii.handler:
function spiralAscii(args, ctx) {
  var DEF_SPEED = (typeof args.speed === "number" && args.speed > 0) ? args.speed : 1;

  // Cancel any previous loop so SPA navigation / re-mount doesn't stack rAFs.
  if (window.__cultSpiralStop) {
    try { window.__cultSpiralStop(); } catch (e) {}
  }

  var raf = 0;
  var stopped = false;
  var reduceMotion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function collect() {
    return Array.prototype.slice.call(document.querySelectorAll("pre[data-spiral]"));
  }

  // Measure one character cell (width/height in px) for a given <pre>,
  // caching against the element's computed font so we can derive the grid
  // size from the element's actual rendered dimensions.
  function cellSize(pre) {
    var cs = window.getComputedStyle(pre);
    var fontKey = cs.fontSize + "|" + cs.fontFamily + "|" + cs.lineHeight + "|" + cs.letterSpacing + "|" + cs.fontWeight;
    if (pre.__cellFontKey === fontKey && pre.__cellW > 0 && pre.__cellH > 0) {
      return { w: pre.__cellW, h: pre.__cellH };
    }
    var probe = document.createElement("span");
    probe.style.position = "absolute";
    probe.style.visibility = "hidden";
    probe.style.whiteSpace = "pre";
    probe.style.font = cs.font;
    probe.style.fontFamily = cs.fontFamily;
    probe.style.fontSize = cs.fontSize;
    probe.style.fontWeight = cs.fontWeight;
    probe.style.letterSpacing = cs.letterSpacing;
    probe.style.lineHeight = cs.lineHeight;
    // 10 columns x 1 row of a wide glyph for a stable average.
    probe.textContent = "MMMMMMMMMM";
    document.body.appendChild(probe);
    var rect = probe.getBoundingClientRect();
    document.body.removeChild(probe);
    var w = rect.width / 10;
    var lh = parseFloat(cs.lineHeight);
    var h = (lh > 0 ? lh : rect.height);
    if (!(w > 0)) w = parseFloat(cs.fontSize) * 0.6;
    if (!(h > 0)) h = parseFloat(cs.fontSize);
    pre.__cellFontKey = fontKey;
    pre.__cellW = w;
    pre.__cellH = h;
    return { w: w, h: h };
  }

  function config(pre, rect) {
    var word = pre.getAttribute("data-spiral") || "CULT";
    if (word.length === 0) word = "CULT";
    var speed = parseFloat(pre.getAttribute("data-spiral-speed"));
    var cell = cellSize(pre);
    // Derive grid from the element's real pixel size so it always fills it.
    var cols = Math.max(8, Math.ceil(rect.width / cell.w));
    var rows = Math.max(8, Math.ceil(rect.height / cell.h));
    return {
      chars: word.split(""),
      cols: cols,
      rows: rows,
      speed: (speed > 0 ? speed : DEF_SPEED)
    };
  }

  function render(pre, rect, t) {
    var c = config(pre, rect);
    var COLS = c.cols;
    var ROWS = c.rows;
    var chars = c.chars;
    var n = chars.length;
    var cx = COLS / 2;
    var cy = ROWS / 2;
    // Scale the spiral arms to the grid so the pattern fills the whole card
    // regardless of aspect ratio, rather than living in a fixed-radius blob.
    var maxR = Math.sqrt(cx * cx + cy * cy);
    var rScale = 6 / Math.max(1, maxR);
    var out = "";
    for (var y = 0; y < ROWS; y++) {
      for (var x = 0; x < COLS; x++) {
        var dx = (x - cx);
        var dy = (y - cy);
        var r = Math.sqrt(dx * dx + dy * dy);
        var a = Math.atan2(dy, dx);
        var spiral = Math.sin(a * 5 + Math.log(r * rScale + 1) * 6 - t * 0.0012 * c.speed);
        if (spiral > 0.1 && r > 4) {
          var idx = Math.floor(r + a + t * 0.005 * c.speed) % n;
          out += chars[((idx % n) + n) % n];
        } else {
          out += " ";
        }
      }
      out += "\n";
    }
    pre.textContent = out;
  }

  function frame(now) {
    if (stopped) return;
    var list = collect();
    for (var k = 0; k < list.length; k++) {
      var pre = list[k];
      if (!pre.isConnected) continue;
      var rect = pre.getBoundingClientRect();
      if (!(rect.width > 0) || !(rect.height > 0)) continue;
      var onscreen = rect.bottom > 0 && rect.top < (window.innerHeight || document.documentElement.clientHeight) && rect.right > 0 && rect.left < (window.innerWidth || document.documentElement.clientWidth);
      if (onscreen) {
        render(pre, rect, now);
      }
    }
    raf = requestAnimationFrame(frame);
  }

  function stop() {
    stopped = true;
    if (raf) cancelAnimationFrame(raf);
    window.__cultSpiralStop = null;
  }
  window.__cultSpiralStop = stop;

  if (reduceMotion) {
    var staticList = collect();
    for (var s = 0; s < staticList.length; s++) {
      var sr = staticList[s].getBoundingClientRect();
      if (sr.width > 0 && sr.height > 0) render(staticList[s], sr, 0);
    }
    ctx.triggerActionEvent("ready", {});
    return;
  }

  var attempts = 0;
  function begin() {
    attempts++;
    if (collect().length > 0) {
      raf = requestAnimationFrame(frame);
      ctx.triggerActionEvent("ready", {});
      return;
    }
    if (attempts < 60 && !stopped) {
      setTimeout(begin, 80);
    }
  }
  begin();
}

spiralVortex.handler:
function spiralVortex(args, ctx) {
  var DEF_SPEED = (typeof args.speed === "number" && args.speed > 0) ? args.speed : 1;

  // Cancel any previous loop so SPA navigation / re-mount doesn't stack rAFs.
  if (window.__cultVortexStop) {
    try { window.__cultVortexStop(); } catch (e) {}
  }

  var raf = 0;
  var stopped = false;
  var reduceMotion = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  function collect() {
    return Array.prototype.slice.call(document.querySelectorAll("pre[data-vortex]"));
  }

  // Measure one character cell (width/height in px) for a given <pre>,
  // caching against the element's computed font so we can derive the grid
  // size from the element's actual rendered dimensions.
  function cellSize(pre) {
    var cs = window.getComputedStyle(pre);
    var fontKey = cs.fontSize + "|" + cs.fontFamily + "|" + cs.lineHeight + "|" + cs.letterSpacing + "|" + cs.fontWeight;
    if (pre.__cellFontKey === fontKey && pre.__cellW > 0 && pre.__cellH > 0) {
      return { w: pre.__cellW, h: pre.__cellH };
    }
    var probe = document.createElement("span");
    probe.style.position = "absolute";
    probe.style.visibility = "hidden";
    probe.style.whiteSpace = "pre";
    probe.style.font = cs.font;
    probe.style.fontFamily = cs.fontFamily;
    probe.style.fontSize = cs.fontSize;
    probe.style.fontWeight = cs.fontWeight;
    probe.style.letterSpacing = cs.letterSpacing;
    probe.style.lineHeight = cs.lineHeight;
    probe.textContent = "MMMMMMMMMM";
    document.body.appendChild(probe);
    var rect = probe.getBoundingClientRect();
    document.body.removeChild(probe);
    var w = rect.width / 10;
    var lh = parseFloat(cs.lineHeight);
    var h = (lh > 0 ? lh : rect.height);
    if (!(w > 0)) w = parseFloat(cs.fontSize) * 0.6;
    if (!(h > 0)) h = parseFloat(cs.fontSize);
    pre.__cellFontKey = fontKey;
    pre.__cellW = w;
    pre.__cellH = h;
    return { w: w, h: h };
  }

  function config(pre, rect) {
    var word = pre.getAttribute("data-vortex") || "CULT";
    if (word.length === 0) word = "CULT";
    var speed = parseFloat(pre.getAttribute("data-vortex-speed"));
    var cell = cellSize(pre);
    var cols = Math.max(8, Math.ceil(rect.width / cell.w));
    var rows = Math.max(8, Math.ceil(rect.height / cell.h));
    return {
      chars: word.split(""),
      cols: cols,
      rows: rows,
      speed: (speed > 0 ? speed : DEF_SPEED)
    };
  }

  // Sparse -> dense halftone ramp. Low spiral values pick sparse glyphs,
  // high values pick dense ones, giving a gradient/halftone falloff.
  var RAMP = " ...:::CULTCULT";

  function render(pre, rect, t) {
    var c = config(pre, rect);
    var COLS = c.cols;
    var ROWS = c.rows;
    var chars = c.chars;
    var n = chars.length;
    var cx = COLS / 2;
    var cy = ROWS / 2;
    // Scale the spiral arms to the grid so the pattern fills the whole card
    // regardless of aspect ratio.
    var maxR = Math.sqrt(cx * cx + cy * cy);
    var rScale = 6 / Math.max(1, maxR);
    var rampMax = RAMP.length - 1;
    var out = "";
    for (var y = 0; y < ROWS; y++) {
      for (var x = 0; x < COLS; x++) {
        var dx = (x - cx);
        var dy = (y - cy);
        var r = Math.sqrt(dx * dx + dy * dy);
        var a = Math.atan2(dy, dx);
        // Per-cell pseudo-random grain to break up the perfect arms.
        var nse = Math.sin(x * 12.9 + y * 78.2) * 43758.5;
        var jitter = (nse - Math.floor(nse)) * 0.25;
        // 3 arms, tight winding (6), fast rotation, aggressive pull-to-center.
        var spiral = Math.sin(a * 3 + Math.log(r * rScale + 1) * 6 - t * 0.003 * c.speed) + jitter;
        if (spiral > -0.3 && r > 2) {
          // Map spiral value to ramp weight: sparse where low, dense where high.
          var v = (spiral + 1) / 2;
          if (v < 0) v = 0; else if (v > 1) v = 1;
          var rc = RAMP[Math.floor(v * rampMax)];
          if (rc === " ") {
            out += " ";
          } else if (rc === "." || rc === ":") {
            out += rc;
          } else {
            // Dense zone: use the word's characters for the premium fill.
            var idx = Math.floor(r + a + t * 0.005 * c.speed) % n;
            out += chars[((idx % n) + n) % n];
          }
        } else {
          out += " ";
        }
      }
      out += "\n";
    }
    pre.textContent = out;
  }

  function frame(now) {
    if (stopped) return;
    var list = collect();
    for (var k = 0; k < list.length; k++) {
      var pre = list[k];
      if (!pre.isConnected) continue;
      var rect = pre.getBoundingClientRect();
      if (!(rect.width > 0) || !(rect.height > 0)) continue;
      var onscreen = rect.bottom > 0 && rect.top < (window.innerHeight || document.documentElement.clientHeight) && rect.right > 0 && rect.left < (window.innerWidth || document.documentElement.clientWidth);
      if (onscreen) {
        render(pre, rect, now);
      }
    }
    raf = requestAnimationFrame(frame);
  }

  function stop() {
    stopped = true;
    if (raf) cancelAnimationFrame(raf);
    window.__cultVortexStop = null;
  }
  window.__cultVortexStop = stop;

  if (reduceMotion) {
    var staticList = collect();
    for (var s = 0; s < staticList.length; s++) {
      var sr = staticList[s].getBoundingClientRect();
      if (sr.width > 0 && sr.height > 0) render(staticList[s], sr, 0);
    }
    ctx.triggerActionEvent("ready", {});
    return;
  }

  var attempts = 0;
  function begin() {
    attempts++;
    if (collect().length > 0) {
      raf = requestAnimationFrame(frame);
      ctx.triggerActionEvent("ready", {});
      return;
    }
    if (attempts < 60 && !stopped) {
      setTimeout(begin, 80);
    }
  }
  begin();
}

autoScrollLoop.handler:
function autoScrollLoop(args, ctx) {
  const id = args.elementId
  const pxPerSec = Number(args.speed) || 40
  function start() {
    const track = document.getElementById(id)
    if (!track) {
      // Element not mounted yet; retry shortly.
      setTimeout(start, 120)
      return
    }
    // Guard against attaching more than once per element.
    if (track._ncAutoScrollAttached) return
    track._ncAutoScrollAttached = true

    let paused = false
    let userActiveUntil = 0
    let last = null

    const pause = () => { paused = true }
    const resume = () => { paused = false }
    // While the user is actively scrolling/dragging, hold off the auto-advance briefly.
    const bumpUser = () => { userActiveUntil = performance.now() + 1200 }

    track.addEventListener("mouseenter", pause)
    track.addEventListener("mouseleave", resume)
    track.addEventListener("focusin", pause)
    track.addEventListener("focusout", resume)
    track.addEventListener("pointerdown", bumpUser)
    track.addEventListener("touchstart", bumpUser, { passive: true })
    track.addEventListener("wheel", bumpUser, { passive: true })
    track.addEventListener("scroll", () => {
      // Keep the loop seamless even when the user scrolls manually:
      // the content is duplicated, so half the scrollWidth is one full set.
      const half = track.scrollWidth / 2
      if (half > 0) {
        if (track.scrollLeft >= half) {
          track.scrollLeft = track.scrollLeft - half
        } else if (track.scrollLeft <= 0) {
          track.scrollLeft = track.scrollLeft + half
        }
      }
    }, { passive: true })

    function frame(now) {
      if (last == null) last = now
      const dt = (now - last) / 1000
      last = now
      const half = track.scrollWidth / 2
      const userActive = now < userActiveUntil
      if (!paused && !userActive && half > 0) {
        let next = track.scrollLeft + pxPerSec * dt
        if (next >= half) {
          next = next - half
        }
        track.scrollLeft = next
      }
      requestAnimationFrame(frame)
    }
    requestAnimationFrame(frame)
    ctx.triggerActionEvent("ready", { elementId: id })
  }
  start()
}

getTimezone.handler:
function getTimezone() {
  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
    return tz ? tz.replace(/_/g, ' ').replace(/\//g, ', ') : "Unknown Location";
  } catch(e) {
    return "Unknown Location";
  }
}

PlayLottieAnimation.handler:
/**
 * @param {Args} args
 * @param {Ctx} ctx
 */
function PlayLottieAnimation (args, ctx) {
  const element = typeof args.element == "string" ? document.getElementById(args.element) : args.element;
  const dotLottie = element?._dotLottieCommonPlayer;
  if (!dotLottie) { 
    return
  }
  if (args.play) {
   dotLottie.play()
  } else {
    dotLottie.pause()   
  }
}

