      break; // Found the leftmost visible slide, no need to continue
    }
  }

  if (nextSlide) {
    // Scroll the next slide into view
    nextSlide.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'start' });
  }
}

